SELECT MAX(CASE WHEN ga.SEC_SNAME LIKE '%宁德时代%' THEN ga.SEC_SNAME END) AS `公司一`, ROUND(MAX(CASE WHEN ga.SEC_SNAME LIKE '%宁德时代%' THEN vf.F110101 END) / 10000, 1) AS `公司一归母净利润(万)`, MAX(CASE WHEN ga.SEC_SNAME LIKE '%招商银行%' THEN ga.SEC_SNAME END) AS `公司二`, ROUND(MAX(CASE WHEN ga.SEC_SNAME LIKE '%招商银行%' THEN vf.F110101 END) / 10000, 1) AS `公司二归母净利润(万)`, CASE WHEN MAX(CASE WHEN ga.SEC_SNAME LIKE '%宁德时代%' THEN vf.F110101 END) > MAX(CASE WHEN ga.SEC_SNAME LIKE '%招商银行%' THEN vf.F110101 END) THEN MAX(CASE WHEN ga.SEC_SNAME LIKE '%宁德时代%' THEN ga.SEC_SNAME END) WHEN MAX(CASE WHEN ga.SEC_SNAME LIKE '%宁德时代%' THEN vf.F110101 END) < MAX(CASE WHEN ga.SEC_SNAME LIKE '%招商银行%' THEN vf.F110101 END) THEN MAX(CASE WHEN ga.SEC_SNAME LIKE '%招商银行%' THEN ga.SEC_SNAME END) ELSE '相同' END AS `归母净利润更高者`, ROUND(ABS(MAX(CASE WHEN ga.SEC_SNAME LIKE '%宁德时代%' THEN vf.F110101 END) - MAX(CASE WHEN ga.SEC_SNAME LIKE '%招商银行%' THEN vf.F110101 END)) / 10000, 1) AS `高出金额(万)` FROM VIEW_STK_FIN_IDX vf LEFT JOIN GET_A_SEC_CODE ga ON vf.COMCODE = ga.COMCODE WHERE (ga.SEC_SNAME LIKE '%宁德时代%' OR ga.SEC_SNAME LIKE '%招商银行%') AND vf.ENDDATE = '2025-12-31 00:00:00' AND vf.F110101 IS NOT NULL AND vf.ISVALID = 1 AND ga.ISVALID = 1;
